        self._preprocess()

    def _preprocess(self):
        for i in range(1, self.h + 1):
            for j in range(1, self.w + 1):
                self._cumsum[i][j] = (
                    self.a[i - 1][j - 1]
                    + self._cumsum[i][j - 1]
                    + self._cumsum[i - 1][j]
                    - self._cumsum[i - 1][j - 1]
                )

    def query(self, h1, h2, w1, w2):
        return (
            self._cumsum[h2][w2]
            - self._cumsum[h1][w2]
            - self._cumsum[h2][w1]
            + self._cumsum[h1][w1]
